Q: How do I achive a grainy effect using an SVG after inlining it from a file? A: <p>Problem with IDs in SVG is that they are global.<br />
So it works fine for 1 SVG, but the second SVG will reference the ID in the first SVG (equal IDs)</p>
<p>You can generate unique SVGs with some elbow grease.</p>
<p>Easier is to wrap the SVG creation inside a native Web Component<br />
AND use shadowDOM so nothing leaks out.</p>
<p>See: <a href="https://jsfiddle.net/WebComponents/76v3whyg/" rel="nofollow noreferrer">https://jsfiddle.net/WebComponents/76v3whyg/</a></p>
<p>Same code inside StackOverflow:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;noised-svg frequency="0.05"&gt;&lt;/noised-svg&gt;
&lt;noised-svg frequency="0.1"&gt;&lt;/noised-svg&gt;
&lt;noised-svg frequency="0.99"&gt;&lt;/noised-svg&gt;

&lt;script&gt;
  !(() =&gt; { // IIFE so script can be placed anywhere without polluting global scope, and to allow use of `const` and `let` without block scope issues
    const DEFAULT_FREQUENCY = "0.65";
    const DEFAULT_SIZE = "120px";
    const FILTER_PREFIX = "noise-filter";
    const RANGE_MIN = "0.01";
    const RANGE_MAX = "0.99";
    const RANGE_STEP = "0.01";

    /**
     * Create a regular DOM element with properties, attributes, styles, and children.
     */
    const createElement = (tag, props = {}) =&gt; {
      const { attrs = {}, styles = {}, append = [], NS = false, ...remainingProps } = props;
      const element = NS ? document.createElementNS(NS, tag) : document.createElement(tag);
      for (const [key, value] of Object.entries(remainingProps)) {
        try {
          element[key] = value;
        } catch {
          if (value !== undefined &amp;&amp; value !== null) element.setAttribute(key, value);
        }
      }
      for (const [key, value] of Object.entries(attrs)) element.setAttribute(key, value);
      for (const [key, value] of Object.entries(styles)) element.style[key] = value;
      element.append(...[append].flat(9));
      return element;
    };
    const createSVGElement = (tag, props = {}) =&gt; createElement(tag, { NS: "http://www.w3.org/2000/svg", ...props });

    // ********************************************************************* &lt;noised-svg&gt;
    /**
     * Web Component that renders a noisy SVG surface with an inline density control.
     */
    customElements.define("noised-svg", class extends HTMLElement {
      static get observedAttributes() {
        return ["frequency"];
      }

      constructor() {
        super() // sets AND returns `this` scope
          .attachShadow({ mode: "open" }) // sets AND returns `this.shadowRoot`
          .append(
            createElement("style", {
              textContent:
                /*css*/`:host {display:inline-block}` +
                /*css*/`noise-stage {display:grid;gap:20px;justify-items:center}` +
                /*css*/`noise-container {position:relative;display:block;width:${DEFAULT_SIZE};height:${DEFAULT_SIZE};filter:contrast(170%) brightness(500%);box-shadow:0 10px 30px rgba(0,0,0,0.1)}` +
                /*css*/`svg {position:absolute;inset:0;display:block;width:100%;height:100%}` +
                /*css*/`gradient-overlay {position:absolute;inset:0;display:block;background:linear-gradient(90deg, black, transparent)}` +
                /*css*/`noise-controls {display:flex;align-items:center;gap:.5rem;padding:15px;border-radius:8px;background:white;box-shadow:0 4px 10px rgba(0,0,0,0.1);font-family:sans-serif}` +
                /*css*/`noise-value {display:inline-block;min-width:3ch}`,
            }),
            // UNdefined Custom Elements &lt;noise-stage&gt; used for layout and styling only, no behavior, no DIV soup
            createElement("noise-stage", {
              append: [
                createElement("noise-container", {
                  append: [
                    createSVGElement("svg", {
                      attrs: {
                        viewBox: "0 0 300 300",
                        preserveAspectRatio: "none",
                      },
                      append: [
                        createSVGElement("filter", {
                          attrs: { id: `noise-filter` },
                          append: this.__turbulence = createSVGElement("feTurbulence", {
                            attrs: {
                              type: "fractalNoise",
                              baseFrequency: this.frequency,
                              numOctaves: "3",
                            },
                          }),
                        }),
                        createSVGElement("rect", {
                          attrs: {
                            width: "100%",
                            height: "100%",
                            filter: `url(#noise-filter)`,
                          },
                        }),
                      ], // append to svg
                    }), // svg
                    createElement("gradient-overlay"),
                  ], // append to noise-container
                }), // noise-container
                createElement("noise-controls", {
                  styles: { zoom:.8 },
                  append: [
                    createElement("label", {
                      htmlFor: `inputfrequency`,
                      innerHTML: "frequency:",
                    }),
                    this.__slider = createElement("input", {
                      attrs: {
                        id: `inputfrequency`,
                        type: "range",
                        min: RANGE_MIN,
                        max: RANGE_MAX,
                        step: RANGE_STEP,
                        value: this.frequency,
                      },
                      oninput: (evt) =&gt; {
                        this.frequency = evt.target.value;
                      },
                    }),
                    this.__display = createElement("noise-value", {
                      textContent: this.frequency,
                    }),
                  ], // append to noise-controls
                }), // noise-controls
              ], // append to noise-stage
            }), // append to shadowRoot
          ); // append
      } // constructor

      get frequency() {
        return this.getAttribute("frequency") || DEFAULT_FREQUENCY;
      }

      set frequency(value) {
        this.setAttribute("frequency", value);
      }

      attributeChangedCallback(name, oldValue, newValue) {
        if (name !== "frequency" || oldValue === newValue || !this.__turbulence) return;
        this.__turbulence.setAttribute("baseFrequency", newValue || DEFAULT_FREQUENCY);
        this.__slider.value = newValue || DEFAULT_FREQUENCY;
        this.__display.textContent = newValue || DEFAULT_FREQUENCY;
      }
    });
  })();
&lt;/script&gt;</code></pre>
</div>
</div>
</p>

Q: How can I implement custom .swipeActions() in my Scrollview-LazyVStack? A: <p>Try to use this library <a href="https://github.com/PavelAndreev13/AwesomeSwipeActions" rel="nofollow noreferrer">https://github.com/PavelAndreev13/AwesomeSwipeActions</a>, I think it's should solve the problem. This library provided actions as native swipe actions but it works with ScrollView + LazyVStack/HStack. Choose direction swipe via from arg: &quot;.trailing/leading/top/bottom&quot; and that and also do not forget to add coordinator it's need it for action only works for 1 item in the one time</p>
<pre><code>import AwesomeSwipeActions

struct CellView: View {

    @State private var coordinator = AwesomeSwipeCoordinator()

    var body: some View {

        NavigationView {
            ScrollView{
                LazyVStack(spacing: 0) {
                    ForEach(0..&lt;20, id: \.self) { item in
                        CustomCell(model: item)
                            .awesomeSwipeActions(
                                id: item.id,
                                coordinator: coordinator,
                                from: .trailing
                                ) {
                                // Inject Button or NavigationLink is here
                        }

                    }
                }
            }
            .navigationTitle(&quot;SwipeActions&quot;)
            .navigationBarTitleDisplayMode(.inline)
        }
    }
}
</code></pre>

Q: Is my maxHeapify logic correct? I have nested the right child check within the left child check A: <p>I understand the logic of your code, but I have doubts about its correct implementation:</p>
<pre class="lang-cpp prettyprint-override"><code>void maxHeapify(int i)  // should `heap` be a parametr?
    {
        if (leftChild(i) &lt; size()) //this node has a left child, meaning it's not a leaf node
        {
            int largest = i;

            if (heap[leftChild(i)] &gt; heap[largest])
            {
                largest = leftChild(i);
            }

            if (rightChild(i) &lt; size())
            {
                if (heap[rightChild(i)] &gt; heap[largest])
                {
                    largest = rightChild(i);
                }
            }

            if (largest != i)
            {
                // What u want here?
                // I mean, above u compare heap[...] and heap[...], but there u swap indexes
                swap(i, largest);  
                maxHeapify(largest);
            }
        }
    }
</code></pre>
<p>But in general, you are right, because <em>Heap</em> is by definition a <strong>complete</strong>, <strong>balanced</strong>, <strong>binary tree</strong>. If you represent <em>Array</em> on <em>Heap</em>, then <em>Heap</em> will be &quot;filled&quot; in layers: <strong>from top-to-bottom</strong>, <strong>from left-to-right</strong>; therefore, it is not possible for the heap to have &quot;gaps&quot; (then it is no longer a heap). You're kind of &quot;laying&quot; <em>Array</em> on <em>BinaryTree</em> (a bit out of time, but it's like decorating a Christmas tree with lights: you can't skip a part of the tree - you'll have to break the lights into two).</p>
<p><em><strong>Correct</strong></em>:</p>
<pre class="lang-sql prettyprint-override"><code>Fill each layer from left to right
--&gt;        10
          /  \
--&gt;     15    20
       /  \   / \
--&gt;   30  40 50 60
     / \
--&gt; 70 80
</code></pre>
<p><em><strong>Invalid</strong></em>:</p>
<pre class="lang-sql prettyprint-override"><code>--&gt;        10
          /  \
--&gt;     15    20
       /  \   / \
--&gt;   30  40 50 60
     / \
HOW !! 80
</code></pre>
<hr />
<p>Code:</p>
<pre class="lang-cpp prettyprint-override"><code>void maxHeapify(int i, vector&lt;int&gt; &amp;heap)
    {
        int largest = i;
        int left = leftChild(i);
        int right = rightChild(i);

        if (left &lt; heap.size())  // usually, use a `while` loop to reduce the memory overhead of recursive function calls
        {

            if (heap[left] &gt; heap[largest])
            {
                largest = left;
            }

            if (right &lt; heap.size() &amp;&amp; heap[right] &gt; heap[largest])  // If nested `if` statements check the one condition layer by layer, they can be combined into a single `if` statement.
            {
                largest = right;
            }

            if (largest != i)
            {
                swap(heap[i], heap[largest]);  
                maxHeapify(largest, heap);
            }
        }
    }
</code></pre>

Q: Webpage optimization: Should CSS and JS be inserted into the HTML resource after minification? A: <p>It is the same to have linked resources and to embed them in the html page.
However not convenient to use on multiple pages.
Then you have to repeat yourself.</p>

<p>If you put all scripts and css together keep this in mind:</p>

<blockquote>
  <p>In most cases, the bulk of the JavaScript code handles user-initiated events, such as mouse-clicking and dragging. All of these user-triggered events occur after the page is loaded and the onload event is triggered. In order to defer loading of these JavaScripts insert a JavaScript event listener in the head of the containing document that forces the external file to be loaded after the onload event. 
  ( <a href="https://developers.google.com/speed/docs/insights/BlockingJS" rel="nofollow">Google developers tips</a> )</p>
</blockquote>

<p>This is the code-example to make it more clear, the delaying scripts will be loading after the essential page elements have been formed:</p>

<pre><code> // Add a script element as a child of the body
 function downloadJSAtOnload() {
 var element = document.createElement("script");
 element.src = "deferredfunctions.js";
 document.body.appendChild(element);
 }

 // Check for browser support of event handling capability
 if (window.addEventListener)
 window.addEventListener("load", downloadJSAtOnload, false);
 else if (window.attachEvent)
 window.attachEvent("onload", downloadJSAtOnload);
 else window.onload = downloadJSAtOnload;
</code></pre>

Q: How does &lt;a href=&quot;#&quot;&gt; ends up invoking Javascript functions? A: <p>Lets break it down like this.</p>

<p>You first give your <code>href</code> element an ID.</p>

<p><code>&lt;a href="#" id="myID"&gt;My Link&lt;/a&gt;</code></p>

<p>Now this element can be uniquely identified.</p>

<p>The JavaScript to access events on that element would look like this:</p>

<pre><code>// first get the element by id
var myLink = document.getElementById("myID");

// add an event listener to listen for clicks

myLink.addEventListener('click', function(e) {
      alert(e.target.id);
      // prevent the element from invoking its default event,
      // which, in this case would be appending an '#' to the URL
      e.preventDefault();


}, false);
</code></pre>

<p>Here is an <a href="http://fiddle.jshell.net/NwyRP/4/show/" rel="nofollow">example</a></p>
